//! A simple URL parser, re-implemented in pure Rust (std only).
//!
//! Behavior mirrors the reference C++ `url_parser` library:
//! - The fragment is split at the first '#', then the query at the first '?'.
//! - A scheme is recognized only when "://" is present; the scheme is the
//!   substring before it, lowercased.
//! - The authority (only parsed when "://" was found) ends at the first '/'.
//! - The userinfo is the part before the first '@' of the authority.
//! - The host ends at the first ':' of the remaining authority; the rest is
//!   parsed as a port with `std::stoi`-like semantics and must be in 0..=65535.
//! - The stored authority is reconstructed from userinfo/host/port.
//! - `to_string` reassembles the URL, including the authority only when a
//!   scheme is present.
//! - A URL is valid when it has a host or a path.

pub struct URL {
    scheme: String,
    authority: String,
    userinfo: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl URL {
    pub fn new(input: &str) -> URL {
        let mut rest = input;

        let mut fragment = String::new();
        if let Some(pos) = rest.find('#') {
            fragment = rest[pos + 1..].to_string();
            rest = &rest[..pos];
        }

        let mut query = String::new();
        if let Some(pos) = rest.find('?') {
            query = rest[pos + 1..].to_string();
            rest = &rest[..pos];
        }

        let mut scheme = String::new();
        let mut userinfo = String::new();
        let mut host = String::new();
        let mut port: i32 = -1;
        let mut path = String::new();

        let after_scheme;
        if let Some(pos) = rest.find("://") {
            scheme = rest[..pos].to_ascii_lowercase();
            after_scheme = &rest[pos + 3..];

            // Authority runs up to the first '/'; the remainder is the path.
            let (raw_authority, p) = match after_scheme.find('/') {
                Some(slash) => (&after_scheme[..slash], &after_scheme[slash..]),
                None => (after_scheme, ""),
            };
            path = p.to_string();

            // Userinfo is everything before the first '@'.
            let hostport = match raw_authority.find('@') {
                Some(at) => {
                    userinfo = raw_authority[..at].to_string();
                    &raw_authority[at + 1..]
                }
                None => raw_authority,
            };

            // Host runs up to the first ':'; the rest is the port.
            match hostport.find(':') {
                Some(colon) => {
                    host = hostport[..colon].to_string();
                    if let Some(p) = parse_port(&hostport[colon + 1..]) {
                        port = p;
                    }
                }
                None => host = hostport.to_string(),
            }
        } else {
            path = rest.to_string();
        }

        // The authority is rebuilt from its parsed components.
        let mut authority = String::new();
        if !userinfo.is_empty() {
            authority.push_str(&userinfo);
            authority.push('@');
        }
        authority.push_str(&host);
        if port != -1 {
            authority.push(':');
            authority.push_str(&port.to_string());
        }

        URL {
            scheme,
            authority,
            userinfo,
            host,
            port,
            path,
            query,
            fragment,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn authority(&self) -> &str {
        &self.authority
    }

    pub fn userinfo(&self) -> &str {
        &self.userinfo
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn has_scheme(&self) -> bool {
        !self.scheme.is_empty()
    }

    pub fn has_authority(&self) -> bool {
        !self.authority.is_empty()
    }

    pub fn has_userinfo(&self) -> bool {
        !self.userinfo.is_empty()
    }

    pub fn has_host(&self) -> bool {
        !self.host.is_empty()
    }

    pub fn has_port(&self) -> bool {
        self.port != -1
    }

    pub fn has_path(&self) -> bool {
        !self.path.is_empty()
    }

    pub fn has_query(&self) -> bool {
        !self.query.is_empty()
    }

    pub fn has_fragment(&self) -> bool {
        !self.fragment.is_empty()
    }

    pub fn to_string(&self) -> String {
        let mut s = String::new();
        if self.has_scheme() {
            s.push_str(&self.scheme);
            s.push_str("://");
            s.push_str(&self.authority);
        }
        s.push_str(&self.path);
        if self.has_query() {
            s.push('?');
            s.push_str(&self.query);
        }
        if self.has_fragment() {
            s.push('#');
            s.push_str(&self.fragment);
        }
        s
    }

    pub fn is_valid(&self) -> bool {
        self.has_host() || self.has_path()
    }
}

/// Parse a port with `std::stoi`-like semantics: skip leading whitespace,
/// accept an optional sign, then consume digits (stopping at the first
/// non-digit). The value must fit in an i32 and lie in 0..=65535.
fn parse_port(s: &str) -> Option<i32> {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }
    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }
    if i >= bytes.len() || !bytes[i].is_ascii_digit() {
        return None;
    }
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value * 10 + (bytes[i] - b'0') as i64;
        if value > i32::MAX as i64 + 1 {
            return None; // std::stoi would throw std::out_of_range
        }
        i += 1;
    }
    let value = if negative { -value } else { value };
    if value < i32::MIN as i64 || value > i32::MAX as i64 {
        return None;
    }
    if (0..=65535).contains(&value) {
        Some(value as i32)
    } else {
        None
    }
}

