mod url_parser;

use url_parser::URL;

fn b2i(b: bool) -> i32 {
    if b {
        1
    } else {
        0
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let parser = URL::new(&args[1]);

    // Test all getters
    println!("{}", parser.scheme());
    println!("{}", parser.authority());
    println!("{}", parser.userinfo());
    println!("{}", parser.host());
    println!("{}", parser.port());
    println!("{}", parser.path());
    println!("{}", parser.query());
    println!("{}", parser.fragment());

    // Test all has_* methods
    println!("{}", b2i(parser.has_scheme()));
    println!("{}", b2i(parser.has_authority()));
    println!("{}", b2i(parser.has_userinfo()));
    println!("{}", b2i(parser.has_host()));
    println!("{}", b2i(parser.has_port()));
    println!("{}", b2i(parser.has_path()));
    println!("{}", b2i(parser.has_query()));
    println!("{}", b2i(parser.has_fragment()));

    // Test to_string and is_valid
    println!("{}", parser.to_string());
    println!("{}", b2i(parser.is_valid()));
}

